def build():
    rows=[]
    for domain,group in GROUPS.items():
        for pair in group.split('|'):
            forms,definition=pair.split('=',1);forms=forms.split('/')
            rows.append(dict(term=forms[0],forms=forms,meaning=[{'definition':definition,'context_hints':[]}],domain=domain,
                register='мат' if forms[0] in ('бля','нахуй','заебись','ебать') else 'разговорный',language='ru',confidence=.9,
                status='confirmed',source='seed',seen_count=0,chats_count=0,first_seen=None,last_seen=None,context_hints=[]))
    # Explicit ambiguity: no default meaning outside disambiguating context.
    multi={
     'лук':[('растение, используемое в пищу',['овощ','суп','нарезать']),('сочетание одежды',['одежда','образ','стиль'])],
     'пара':[('учебное занятие',['занятие','университет','расписание']),('два предмета',['два','носки','ботинки'])],
     'бит':[('единица цифровой информации',['байт','данные','память']),('ритмическая основа',['ритм','музыка','композиция'])],
     'кк':[('тысяча тысяч, миллион',['число','сумма','миллион']),('краткое подтверждение согласия',['согласен','ладно','договорились'])]
    }
    for term,meanings in multi.items():
        record=next((r for r in rows if r['term']==term),None)
        if record is None:
            record=dict(rows[0],term=term,forms=[term],domain='общение');rows.append(record)
        record['meaning']=[{'definition':d,'context_hints':h} for d,h in meanings]
    assert len({r['term'] for r in rows})==len(rows)
    target=Path(__file__).resolve().parents[1]/'core/config/slang.json'
    target.write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    print('seed_records',len(rows))

if __name__=='__main__':build()
